// Connection settings come from the n8n container environment (docker-compose.yml);
// the defaults work with the demo data. The webhook payload (if any) is kept as "trigger".
const e = $env;
const first = $input.first().json;
return [{ json: {
  api: (e.FM_API_URL || 'http://backend:8000/api/v1').replace(/\/$/, ''),
  email: e.FM_API_EMAIL || 'cfo@futuremirror.demo',
  password: e.FM_API_PASSWORD || 'FutureMirror!2026',
  tenant: e.FM_API_TENANT || 'nile-engineering',
  alertTo: e.FM_ALERT_EMAIL || 'approvers@example.com',
  hrTo: e.FM_HR_EMAIL || 'hr@example.com',
  from: e.FM_FROM_EMAIL || 'future-mirror@example.com',
  appUrl: (e.FM_APP_URL || 'http://localhost:8080').replace(/\/$/, ''),
  trigger: first.body || {},
}}];

// CONSEQUENTIAL scenario. The platform blocks live runs unless the decision is approved and
// external actions are enabled (policies GOV-003 / GOV-014). Even then, this workflow only emails a
// draft to HR for manual handling. It never contacts contractors, HR or ERP systems.
const t = $('Settings').first().json.trigger;
if (!t.idempotency_key) return [];
return [{ json: { subject: `ACTION NEEDED (manual): contractor reduction notices for decision ${t.decision_id || ''}`,
  text: `Future Mirror AI recorded an approved request to prepare contractor reduction notices.\n\n` +
        `Decision: ${t.decision_id || ''}\nRequested at: ${t.requested_at || ''}\n\n` +
        `No notices were sent. Please prepare and issue them manually through the normal HR and legal process.` } }];
